CREATE TABLE disciplines (
 id uuid PRIMARY KEY, created_at timestamp NOT NULL, updated_at timestamp NOT NULL, deleted boolean NOT NULL DEFAULT false,
 code varchar(64) NOT NULL UNIQUE CHECK (code ~ '^[A-Z][A-Z0-9_]{1,63}$'), display_name varchar(200) NOT NULL, description text NOT NULL,
 active boolean NOT NULL, format varchar(16) NOT NULL CHECK (format = 'STANDARD'), question_type varchar(32) NOT NULL CHECK (question_type = 'SINGLE_CHOICE'),
 options_count integer NOT NULL CHECK (options_count = 4), question_count integer NOT NULL CHECK (question_count = 5),
 base_question_seconds integer NOT NULL CHECK (base_question_seconds > 0), overtime_seconds integer NOT NULL CHECK (overtime_seconds > 0),
 display_order integer NOT NULL, timings jsonb NOT NULL, schedules jsonb NOT NULL, topics jsonb NOT NULL DEFAULT '[]'
);
CREATE TABLE rank_tiers (
 id uuid PRIMARY KEY, created_at timestamp NOT NULL, updated_at timestamp NOT NULL, deleted boolean NOT NULL DEFAULT false,
 code varchar(32) NOT NULL UNIQUE, display_name varchar(100) NOT NULL, league_code varchar(32) NOT NULL,
 floor_rating integer NOT NULL UNIQUE CHECK (floor_rating >= 0), ceiling_exclusive integer, division_number integer,
 CHECK (ceiling_exclusive IS NULL OR ceiling_exclusive > floor_rating), CHECK (division_number IS NULL OR division_number BETWEEN 1 AND 3)
);
